const assert = require('node:assert/strict');

// Helper building a Source/Lease pair (shape of src/source.ts) that records
// opens, closes and reads, with injectable failures.
function makeSource({ values, readError, closeError, mapperErrorOn }) {
  const state = { opens: 0, closes: 0, reads: [], lease: null };
  const source = {
    open: async () => {
      state.opens++;
      state.lease = {
        read: async () => {
          const value = values.length ? values.shift() : null;
          state.reads.push(value);
          if (readError) throw readError;
          return value;
        },
        close: async () => {
          state.closes++;
          if (closeError) throw closeError;
        },
      };
      return state.lease;
    },
  };
  return { source, state };
}

async function exhaustion() {
  const { source, state } = makeSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const found = [];
  for await (const value of service.stream()) found.push(value);
  assert.deepEqual(found, ['A', 'B']);
  assert.equal(state.opens, 1);
  assert.equal(state.closes, 1);
  // one read per next(): a, b, then the read establishing exhaustion
  assert.deepEqual(state.reads, ['a', 'b', null]);
}

async function lazyOpenAndNoReadAheadOnBreak() {
  const { source, state } = makeSource({ values: ['a', 'b', 'c'] });
  const service = new EventService(source);
  const gen = service.stream();
  assert.equal(state.opens, 0, 'must not open before first iteration');
  const first = await gen.next();
  assert.equal(first.value, 'A');
  assert.equal(state.opens, 1);
  assert.deepEqual(state.reads, ['a'], 'exactly one read per next()');
  await gen.return(); // consumer break
  assert.equal(state.closes, 1);
  assert.deepEqual(state.reads, ['a'], 'must not read ahead past last consumed record');
  await gen.next();
  assert.equal(state.closes, 1, 'closed exactly once');
}

async function returningUnopenedGenerator() {
  const { source, state } = makeSource({ values: ['a'] });
  const service = new EventService(source);
  const gen = service.stream();
  await gen.return();
  assert.equal(state.opens, 0, 'unopened generator must not open');
  assert.equal(state.closes, 0, 'unopened generator must not close');
}

async function readFailure() {
  const readError = new Error('read boom');
  const { source, state } = makeSource({ values: ['a'], readError });
  const service = new EventService(source);
  await assert.rejects(
    async () => { for await (const value of service.stream()) void value; },
    (error) => error === readError,
  );
  assert.equal(state.closes, 1);
}

async function mapperFailure() {
  const mapperError = new Error('mapper boom');
  const { source, state } = makeSource({ values: ['a', 'b'] });
  const service = new EventService(source, () => { throw mapperError; });
  await assert.rejects(
    async () => { for await (const value of service.stream()) void value; },
    (error) => error === mapperError,
  );
  assert.equal(state.closes, 1);
}

async function consumerInjectedThrow() {
  const injected = new Error('injected');
  const { source, state } = makeSource({ values: ['a', 'b'] });
  const service = new EventService(source);
  const gen = service.stream();
  assert.equal((await gen.next()).value, 'A');
  await assert.rejects(() => gen.throw(injected), (error) => error === injected);
  assert.equal(state.closes, 1);
}

async function closeFailureOnExhaustion() {
  const closeError = new Error('close boom');
  const { source, state } = makeSource({ values: [], closeError });
  const service = new EventService(source);
  await assert.rejects(
    async () => { for await (const value of service.stream()) void value; },
    (error) => error === closeError,
  );
  assert.equal(state.closes, 1);
}

async function closeFailurePreservesReadError() {
  const readError = new Error('read boom');
  const closeError = new Error('close boom');
  const { source, state } = makeSource({ values: ['a'], readError, closeError });
  const service = new EventService(source);
  await assert.rejects(
    async () => { for await (const value of service.stream()) void value; },
    (error) => error === readError,
  );
  assert.equal(state.closes, 1);
}

async function closeFailurePreservesMapperError() {
  const mapperError = new Error('mapper boom');
  const closeError = new Error('close boom');
  const { source, state } = makeSource({ values: ['a'], closeError });
  const service = new EventService(source, () => { throw mapperError; });
  await assert.rejects(
    async () => { for await (const value of service.stream()) void value; },
    (error) => error === mapperError,
  );
  assert.equal(state.closes, 1);
}

async function closeFailurePreservesInjectedError() {
  const injected = new Error('injected');
  const closeError = new Error('close boom');
  const { source, state } = makeSource({ values: ['a'], closeError });
  const service = new EventService(source);
  const gen = service.stream();
  assert.equal((await gen.next()).value, 'A');
  await assert.rejects(() => gen.throw(injected), (error) => error === injected);
  assert.equal(state.closes, 1);
}

async function main() {
  const tests = [
    exhaustion,
    lazyOpenAndNoReadAheadOnBreak,
    returningUnopenedGenerator,
    readFailure,
    mapperFailure,
    consumerInjectedThrow,
    closeFailureOnExhaustion,
    closeFailurePreservesReadError,
    closeFailurePreservesMapperError,
    closeFailurePreservesInjectedError,
  ];
  for (const test of tests) await test();
}

module.exports = main();
